    cutoff = (datetime.now(timezone.utc) - timedelta(days=days)).replace(tzinfo=None).isoformat(timespec="seconds")
    rows = [r for r in classify.get_ranked(tiers=tiers, limit=500) if r["announced_at"] >= cutoff]
    return rows[:limit]


