def today(days: int = Query(7, ge=1, le=60), limit: int = Query(25, ge=1, le=100)) -> dict:
    tickers = set(_universe())
    must = [r for r in _recent(("MUST_READ",), days, 500) if r["ticker"] in tickers][:limit]
