<!doctype html><body style="margin:0;background:#888">
<iframe id="f" src="/#today" width="375" height="780" style="border:0;background:#fff"></iframe>
<pre id="log" style="position:absolute;left:400px;top:0;background:#fff;font:12px monospace;width:700px;white-space:pre-wrap"></pre>
<script>
const log = (m) => { document.getElementById("log").textContent += m + "\n"; };
const f = document.getElementById("f"); const errors = [];
const sleep = (ms) => new Promise(r => setTimeout(r, ms));
async function until(fn, ms = 20000) { const t = Date.now(); while (Date.now() - t < ms) { try { const v = fn(); if (v) return v; } catch {} await sleep(200); } return null; }
f.addEventListener("load", async () => {
  const w = f.contentWindow, d = () => f.contentDocument;
  w.addEventListener("error", e => errors.push("error: " + e.message));
  w.addEventListener("unhandledrejection", e => errors.push("rejection: " + (e.reason && e.reason.message)));
  const origErr = w.console.error; w.console.error = (...a) => { errors.push("console.error: " + a.join(" ")); origErr.apply(w.console, a); };
  const click = (sel, txt) => [...d().querySelectorAll(sel)].find(e => !txt || e.textContent.trim().startsWith(txt))?.click();
  const shot = (name) => log(`[${name}] scrollW=${d().documentElement.scrollWidth} clientW=${d().documentElement.clientWidth} (horizontal overflow: ${d().documentElement.scrollWidth > d().documentElement.clientWidth})`);
  // Today
  await until(() => d().querySelectorAll("#tab-today article").length > 3);
  log("today cards: " + d().querySelectorAll("#tab-today section[aria-label=Filings] article").length + ", alerts: " + d().querySelectorAll("#tab-today section[aria-label='Live alerts'] article").length);
  shot("today");
  click("#tab-today button", "Alert settings"); await sleep(300);
  const range = d().querySelector("#tab-today input[type=range]");
  log("drawer open: " + !!range);
  // set volume to 1.1 and price to 2 then save
  const ranges = d().querySelectorAll("#tab-today input[type=range]");
  ranges[0].value = "1.1"; ranges[0].dispatchEvent(new Event("input", {bubbles:true}));
  ranges[1].value = "2"; ranges[1].dispatchEvent(new Event("input", {bubbles:true}));
  const before = d().querySelectorAll("#tab-today section[aria-label='Live alerts'] article").length;
  click("#tab-today button", "Save & update"); 
  await until(() => d().querySelectorAll("#tab-today section[aria-label='Live alerts'] article").length > before);
  log(`alerts before ${before} -> after ${d().querySelectorAll("#tab-today section[aria-label='Live alerts'] article").length} (demo thresholds)`);
  click("#tab-today button", "Reset defaults"); await sleep(1500);
  log("after reset alerts: " + d().querySelectorAll("#tab-today section[aria-label='Live alerts'] article").length);
  click("#tab-today button", "Worth a Look"); await sleep(400);
  log("worth cards: " + d().querySelectorAll("#tab-today section[aria-label=Filings] article").length);
  click("#tab-today button", "All"); await until(() => d().querySelectorAll("#tab-today section[aria-label=Filings] article").length > 20);
  log("all cards: " + d().querySelectorAll("#tab-today section[aria-label=Filings] article").length);
  click("#tab-today button", "Must Read"); await sleep(300);
  const mg = [...d().querySelectorAll("#tab-today article")].length;
  // Research
  click("button", "Research"); await sleep(300);
  click("#tab-research button", "BAJFINANCE");
  await until(() => d().querySelector("#tab-research h2.text-lg"), 30000);
  log("research PvD items: " + d().querySelectorAll("#tab-research section[aria-label^='Promised'] article").length + ", sections: " + d().querySelectorAll("#tab-research details").length + ", badges: " + [...d().querySelectorAll("#tab-research section[aria-label^='Promised'] article span.rounded-full")].map(e => e.textContent).join("|"));
  shot("research");
  // invalid ticker
  const inp = d().querySelector("#tab-research input"); inp.value = "ZZNOTREAL9"; inp.dispatchEvent(new w.KeyboardEvent("keydown", {key: "Enter"}));
  await until(() => d().querySelector("#tab-research [role=alert]"), 60000);
  log("invalid ticker message: " + (d().querySelector("#tab-research [role=alert] p")?.textContent || "NONE"));
  // Chat
  click("button", "Ask FINN"); await sleep(300);
  log("chat chips: " + d().querySelectorAll("#tab-chat button.rounded-2xl").length);
  click("#tab-chat button", "What are TCS");
  await until(() => d().querySelectorAll("#tab-chat .rounded-bl-sm").length > 0, 90000);
  const reply = d().querySelector("#tab-chat .rounded-bl-sm");
  log("chat reply pills: " + (reply ? reply.querySelectorAll("button").length : 0) + " | text: " + (reply ? reply.textContent.slice(0, 300) : "NONE"));
  shot("chat");
  log("ERRORS: " + (errors.length ? errors.join(" ; ") : "none"));
  log("DONE");
});
</script></body>
